function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('between-hand-control',1);r.onupgradeneeded=()=>r.result.createObjectStore('hand');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
