 $('#record').disabled=recording?false:locked||learned||!tracked||!cameraStream||anchors.length>=12;$('#record').textContent=recording?'■ Stop recording':pendingRecord?'Opening microphone…':'● Record at this gesture';$('#record').classList.toggle('recording',!!recording);$('#sound-name').disabled=locked||learned;$('#learn').hidden=learned;$('#learn').disabled=locked||!anchors.length;$('#learn').textContent=busy?'✧ Learning…':'✧ Learn sounds';$('#listen').hidden=!learned;$('#listen').disabled=locked||!cameraStream||!tracked;$('#listen').textContent=playing?'Ⅱ Pause sound':'▶ Explore with my hand';$('#edit').hidden=!learned;$('#edit').disabled=locked;$('#reset').disabled=busy||restoring;$('#import-drawing').disabled=locked||anchors.length>0;$('#demo').disabled=locked||anchors.length>0;
 document.querySelectorAll('[data-cal]').forEach(b=>b.disabled=locked||!tracked);$('#cal-reset').disabled=locked;$('#map-mode').textContent=recording?'● RECORDING GESTURE':learned?'GESTURE EXPLORATION':'BUILD YOUR MAP';$('#tracking-badge').textContent=!cameraStream?'CAMERA OFF':tracked?'HAND TRACKED':'SHOW ONE HAND';$('#camera-empty').hidden=!!cameraStream;video.hidden=!cameraStream;overlay.hidden=!cameraStream;$('#map-empty').hidden=anchors.length>0;
