function path(points){return points.map((p,i)=>`${i?'L':'M'}${p.x*1000},${p.y*680}`).join(' ')}
function drawMap(){const w=learned?weightsAt(anchors,position):anchors.map(()=>0);let svg='';for(let i=0;i<anchors.length;i++){const a=anchors[i],p=a.points[Math.floor(a.points.length/2)],color=colors[i%12];if(w[i]>.01)svg+=`<path d="M${position.x*1000},${position.y*680}L${p.x*1000},${p.y*680}" fill="none" stroke="${color}" stroke-width="2.5" stroke-dasharray="6 6" opacity=".8"/>`;if(a.points.length>1)svg+=`<path d="${path(a.points)}" fill="none" stroke="${color}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round" opacity=".7"/>`;svg+=`<circle cx="${p.x*1000}" cy="${p.y*680}" r="16" fill="${color}" stroke="#fffefa" stroke-width="3"/><text x="${Math.max(60,Math.min(940,p.x*1000))}" y="${Math.max(25,p.y*680-29)}" text-anchor="middle" class="hand-dot-label">${esc(a.name)}</text>`}if(recording?.points.length>1)svg+=`<path d="${path(recording.points)}" fill="none" stroke="#b47f66" stroke-width="5" stroke-dasharray="7 5"/>`;if(cameraStream&&tracked)svg+=`<circle cx="${position.x*1000}" cy="${position.y*680}" r="23" fill="#7e9a6240"/><circle cx="${position.x*1000}" cy="${position.y*680}" r="12" fill="#fffefa" stroke="#627e4f" stroke-width="3"/>`;$('#gesture-scene').innerHTML=svg}
function setTracked(value){if(tracked===value)return;tracked=value;if(master&&playing)master.gain.setTargetAtTime(value?+$('#volume').value/100:0,ctx.currentTime,.09);ui()}
const bones=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[5,9],[9,10],[10,11],[11,12],[9,13],[13,14],[14,15],[15,16],[13,17],[0,17],[17,18],[18,19],[19,20]];
