async function audio(){if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=0;master.connect(ctx.destination)}await ctx.resume()}
function stopAudio(){if(node){node.disconnect();node.port.close();node=null}playing=false}
