$('#learn').onclick=async()=>{if(busy||recording||!anchors.length)return;stopAudio();const token=epoch;busy=true;ui();try{await audio();const {analyzeMouth}=await import('./mouth-dsp.mjs'),{analyzeTrajectory}=await import('./trajectory-dsp.mjs');for(const a of anchors){if(token!==epoch)return;if(a.model&&(a.points.length===1||a.trajectory))continue;status('Learning '+a.name+'…');await new Promise(r=>setTimeout(r,0));const {channels,rate}=a.audio,mono=new Float32Array(channels[0].length);for(const ch of channels)for(let k=0;k<mono.length;k++)mono[k]+=ch[k]/channels.length;if(a.points.length>1){a.trajectory=await analyzeTrajectory(mono,rate,(n,total)=>status(`Learning ${a.name}: ${n}/${total} active sound frames…`),()=>token!==epoch);a.model=a.trajectory.frames[0].model}else a.model=analyzeMouth(mono,rate)}if(token!==epoch)return;learned=true;save();status('Sound map learned. Show your hand and press Explore with my hand.')}catch(e){status(e.message||'Could not learn these sounds. Please try again.');save()}finally{if(token===epoch){busy=false;ui()}}};
$('#camera-toggle').onclick=()=>cameraStream?stopCamera():startCamera();$('#record').onclick=record;$('#listen').onclick=explore;$('#edit').onclick=()=>{stopAudio();learned=false;save();ui();status('Your sounds are kept. Record more gesture examples, then Learn sounds again.')};$('#volume').oninput=()=>{if(master&&playing)master.gain.setTargetAtTime(tracked?+$('#volume').value/100:0,ctx.currentTime,.05);save()};
function remapExamples(){anchors=anchors.map(a=>({...a,points:a.points.map(p=>p.raw?{...p,...normalizeFeatures(p.raw,cal)}:p)}));save();drawMap()}
document.querySelectorAll('[data-cal]').forEach(button=>button.onclick=()=>{if(!tracked||!raw)return;const key=button.dataset.cal,values=history.map(p=>key==='closed'||key==='open'?p.openness:p.roll).sort((a,b)=>a-b);const value=values[Math.floor(values.length/2)];try{cal=calibrated(cal,key,value);remapExamples();$('#cal-status').textContent='Saved '+button.textContent.replace('Save ','')+'. Gesture examples were adjusted to your range.'}catch(e){$('#cal-status').textContent=e.message}});
$('#cal-reset').onclick=()=>{cal={...DEFAULT_CALIBRATION};remapExamples();$('#cal-status').textContent='Default range restored: open/closed fingers and −45° to +45° tilt.'};
$('#hand-sounds').onclick=e=>{const b=e.target.closest('[data-remove]');if(!b||b.disabled)return;stopAudio();anchors=anchors.filter(a=>a.id!==+b.dataset.remove);learned=false;save();ui();status('Sound removed. The rest of your gesture map is kept.')};
$('#reset').onclick=()=>{epoch++;if(recording){clearTimeout(recording.timeout);recording.stream.getTracks().forEach(t=>t.stop());if(recording.recorder.state==='recording')recording.recorder.stop()}recording=null;pendingRecord=false;stopAudio();anchors=[];nextId=1;learned=false;busy=false;$('#sound-name').value='';save();ui();status('Hand sounds cleared. Your camera calibration and drawing tab are kept.')};
async function readDrawing(){return new Promise((resolve,reject)=>{const r=indexedDB.open('between-sound-landscape');r.onupgradeneeded=()=>{r.transaction.abort()};r.onerror=()=>reject(new Error('No saved drawing sounds found. Record here or load the demo.'));r.onsuccess=()=>{const database=r.result;if(!database.objectStoreNames.contains('landscape')){database.close();reject(new Error('No saved drawing sounds found.'));return}const tx=database.transaction('landscape','readonly'),request=tx.objectStore('landscape').get('current');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);tx.oncomplete=()=>database.close()}})}
$('#import-drawing').onclick=async()=>{if(anchors.length||busy)return;busy=true;ui();try{const snapshot=await readDrawing();const source=snapshot?.anchors?.filter(a=>a.audio)||[];if(!source.length)throw new Error('No saved drawing sounds found. Record here or load the demo.');anchors=structuredClone(source.slice(0,12));nextId=Math.max(...anchors.map(a=>a.id))+1;learned=anchors.every(a=>a.model&&(a.points.length===1||a.trajectory));save();status('Drawing sounds copied into this gesture map. Openness and tilt now control their positions.')}catch(e){status(e.message)}finally{busy=false;ui()}};
$('#demo').onclick=async()=>{if(anchors.length||busy)return;busy=true;ui();try{await audio();const presets=[['Open AH',.85,.2,[[750,140,1],[1150,180,.8],[2600,220,.4]]],['Closed MM',.15,.2,[[250,100,1.3],[1000,180,.12],[2200,250,.025]]],['Round OO',.15,.8,[[350,100,1],[800,130,.5],[2200,250,.15]]],['Bright EE',.85,.8,[[300,90,.6],[2200,180,1],[3000,200,.3]]]];for(const [name,x,y,formants]of presets){const b=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),d=b.getChannelData(0);for(let k=0;k<d.length;k++){const t=k/ctx.sampleRate;if(t<.3||t>1.7)continue;let value=0;for(let h=1;h<=35;h++){let amp=.015/h;for(const [f,w,g]of formants)amp+=g*Math.exp(-.5*((h*145-f)/w)**2)/Math.sqrt(h);value+=amp*Math.sin(2*Math.PI*h*145*t)}d[k]=value*.16*Math.min(1,(t-.3)/.12,(1.7-t)/.12)}anchors.push({id:nextId++,name,points:[{x,y}],audio:audioBytes(b),model:null,trajectory:null})}save();status('Four synthetic mouth sounds loaded. Learn sounds, then enable the camera and explore.')}catch{status('Could not load demo sounds. Please try again.')}finally{busy=false;ui()}};
async function restore(){try{const data=await store('readonly',(s,set)=>{const r=s.get('current');r.onsuccess=()=>set(r.result)});if(data){anchors=data.anchors||[];cal=data.cal||cal;nextId=data.nextId||1;learned=!!data.learned&&anchors.length>0&&anchors.every(a=>a.model);$('#volume').value=data.volume??60;if(anchors.length)status(learned?'Your gesture sounds are restored. Enable the camera and explore.':'Your gesture examples are restored. Continue recording or Learn sounds.')}}catch{$('#storage-status').textContent='Kept in this tab; browser storage unavailable'}finally{restoring=false;ui()}}
$('#help').onclick=()=>$('#guide').showModal();$('#close').onclick=()=>$('#guide').close();window.addEventListener('pagehide',()=>{epoch++;stopCamera();if(recording){clearTimeout(recording.timeout);recording.stream.getTracks().forEach(t=>t.stop())}recording=null;pendingRecord=false;busy=false;worker?.terminate();trackerReady=false;trackerLoading=false});window.addEventListener('pageshow',e=>{if(e.persisted){ui();initTracker()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&(cameraStream||cameraStarting))stopCamera()});ui();restore();initTracker();
